from chb_equ_sub
where
INDENTIFY_MARK = #{indentifyMark}
and REGIST_BANK_CODE = #{registBankCode}
and SUBMIT_STATUS = #{noSubmit}

SELECT count(1)
from CHB_EQU_HOLD
where

	INDENTIFY_MARK = #{INDENTIFY_MARK,jdbcType=VARCHAR}


	and REGIST_BANK_CODE = #{REGIST_BANK_CODE,jdbcType=VARCHAR}


and status !='D'

SELECT SUM(HOLD_INFO)
from
(
select count(1) as HOLD_INFO from CHB_EQU_HOLD
where

	INDENTIFY_MARK = #{INDENTIFY_MARK,jdbcType=VARCHAR}


	and REGIST_BANK_CODE = #{REGIST_BANK_CODE,jdbcType=VARCHAR}


and status !='D'
union all
select count(1) as HOLD_INFO from CHB_EQU_HOLD_CHECK
where

	INDENTIFY_MARK = #{INDENTIFY_MARK,jdbcType=VARCHAR}


	and REGIST_BANK_CODE = #{REGIST_BANK_CODE,jdbcType=VARCHAR}


and status !='D'
)A

